--
-- Table structure for table `frames`
--

DROP TABLE IF EXISTS `frames`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `frames` (
  `FrameId` int NOT NULL AUTO_INCREMENT,
  `FrameNumber` int DEFAULT NULL,
  `Edited` varchar(10) DEFAULT 'NO',
  `StartTime` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `Studio` varchar(100) DEFAULT NULL,
  `TableId` varchar(251) DEFAULT NULL,
  `tableName` varchar(30) DEFAULT NULL,
  `fixedRate` tinyint(1) DEFAULT '0',
  `Duration` int GENERATED ALWAYS AS (timestampdiff(MINUTE,`StartTime`,`OffTime`)) STORED,
  `durationBkp` int DEFAULT NULL,
  `Winner` varchar(251) DEFAULT NULL,
  `Format` varchar(255) DEFAULT NULL,
  `Status` varchar(10) DEFAULT NULL,
  `pauseTime` datetime DEFAULT NULL,
  `resumeTime` datetime DEFAULT NULL,
  `Plus` int DEFAULT NULL,
  `P1` varchar(255) DEFAULT NULL,
  `P2` varchar(255) DEFAULT NULL,
  `P3` varchar(255) DEFAULT NULL,
  `P4` varchar(255) DEFAULT NULL,
  `P5` varchar(255) DEFAULT NULL,
  `P6` varchar(255) DEFAULT NULL,
  `Roaster` int DEFAULT NULL,
  `OffTime` datetime DEFAULT NULL,
  `StartSlot` varchar(100) DEFAULT NULL,
  `StartRate` decimal(5,2) DEFAULT NULL,
  `FirstSlotEnd` datetime DEFAULT NULL,
  `EndSlot` varchar(100) DEFAULT NULL,
  `EndRate` decimal(5,2) DEFAULT '0.00',
  `FirstHalf` decimal(10,2) GENERATED ALWAYS AS (timestampdiff(MINUTE,`StartTime`,if((`FirstSlotEnd` is not null),`FirstSlotEnd`,`OffTime`))) VIRTUAL,
  `SecondHalf` decimal(10,2) GENERATED ALWAYS AS (coalesce(timestampdiff(MINUTE,`FirstSlotEnd`,`OffTime`),0)) STORED,
  `fixedCharge` decimal(10,0) DEFAULT '0',
  `totalMoney2` int DEFAULT NULL,
  `Share` decimal(10,2) GENERATED ALWAYS AS ((`totalMoney2` / `Split`)) STORED,
  `Split` int DEFAULT NULL,
  `LP01` varchar(255) DEFAULT NULL,
  `LP02` varchar(255) DEFAULT NULL,
  `LP03` varchar(255) DEFAULT NULL,
  `LP04` varchar(255) DEFAULT NULL,
  `LP05` varchar(255) DEFAULT NULL,
  `LP06` varchar(255) DEFAULT NULL,
  `LP07` varchar(255) DEFAULT NULL,
  `LP08` varchar(255) DEFAULT NULL,
  `LP09` varchar(255) DEFAULT NULL,
  `LP10` varchar(255) DEFAULT NULL,
  `Looser` varchar(255) DEFAULT NULL,
  `Frames` int GENERATED ALWAYS AS (`Split`) STORED,
  `LooserCoins` int DEFAULT NULL,
  `WinnerCoins` int DEFAULT NULL,
  `LooserStake` decimal(10,2) DEFAULT NULL,
  `WinnerStake` decimal(10,2) DEFAULT NULL,
  `DisplayWon` decimal(10,2) DEFAULT NULL,
  `DisplayLoss` decimal(10,2) DEFAULT NULL,
  `FinalWin` decimal(10,2) DEFAULT NULL,
  `No1` varchar(255) DEFAULT NULL,
  `Discount` decimal(10,2) DEFAULT NULL,
  `gg1` varchar(255) DEFAULT NULL,
  `gg2` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`FrameId`),
  KEY `idx_studio_status_starttime_tableid` (`Studio`,`Status`,`StartTime`,`TableId`),
  KEY `idx_frames_studio` (`Studio`)
) ENGINE=InnoDB AUTO_INCREMENT=44126 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

