--
-- Table structure for table `leaderboard`
--

DROP TABLE IF EXISTS `leaderboard`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `leaderboard` (
  `PlayerID` int NOT NULL AUTO_INCREMENT,
  `players` varchar(255) NOT NULL,
  `Matches_On` int DEFAULT '0',
  `Matches_Off` int DEFAULT '0',
  `Total_Frame` int DEFAULT '0',
  `wins` int GENERATED ALWAYS AS ((`Total_Frame` - `Matches_Off`)) STORED,
  `win_rate` decimal(10,2) GENERATED ALWAYS AS ((case when (`Total_Frame` > 0) then ((`wins` / `Total_Frame`) * 100) else 0 end)) STORED,
  `status` tinyint(1) DEFAULT '0',
  `Loss` int GENERATED ALWAYS AS (`Matches_Off`) STORED,
  `Snookerplus` int GENERATED ALWAYS AS (`Coins`) STORED,
  `Coins` int DEFAULT '25',
  `My_Win` int DEFAULT '0',
  `My_Loss` int DEFAULT '0',
  `Level` varchar(255) DEFAULT NULL,
  `Stage_Name` varchar(100) DEFAULT NULL,
  `Above_20` int DEFAULT NULL,
  `Default_20` int DEFAULT NULL,
  `Link` varchar(255) DEFAULT NULL,
  `Frames_5` int DEFAULT NULL,
  `Bonus_Z` int DEFAULT NULL,
  `Frame_Bonus` int DEFAULT NULL,
  `Decay` int DEFAULT NULL,
  `P_Bonus` int DEFAULT NULL,
  `Recheck` int DEFAULT NULL,
  `studio` varchar(255) NOT NULL,
  `city` varchar(251) DEFAULT NULL,
  `medals` varchar(10) DEFAULT NULL,
  `gg_count` int DEFAULT '0',
  PRIMARY KEY (`PlayerID`),
  UNIQUE KEY `PlayerID` (`PlayerID`),
  UNIQUE KEY `PlayerID_2` (`PlayerID`)
) ENGINE=InnoDB AUTO_INCREMENT=2759 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `leaderboard`
