  `Studio_name` varchar(251) DEFAULT NULL,
  `city` varchar(251) DEFAULT NULL,
  `tables` int DEFAULT NULL,
  `Pin` int DEFAULT NULL,
  `ownerPass` varchar(251) DEFAULT NULL,
  `SecurityKey` varchar(251) DEFAULT NULL,
  `added_On` date DEFAULT NULL,
  `isLeaderBoard` tinyint(1) NOT NULL DEFAULT '1',
  `Table_money` int DEFAULT '0',
  `Goods` int DEFAULT '0',
  `Received` int DEFAULT '0',
  `Credit_Balance` int GENERATED ALWAYS AS (((`Table_money` + `Goods`) - `Received`)) STORED,
  `duration` int DEFAULT '0',
  `fixedRate` tinyint(1) DEFAULT NULL,
  `clublogo` varchar(255) DEFAULT NULL,
  PRIMARY KEY (`Studio`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
