DROP TABLE IF EXISTS `topup`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
 SET character_set_client = utf8mb4 ;
CREATE TABLE `topup` (
  `RecordID` int NOT NULL AUTO_INCREMENT,
  `RecordDate` datetime DEFAULT NULL,
  `UserName` varchar(255) DEFAULT NULL,
  `Amount` decimal(10,2) DEFAULT NULL,
  `studio` varchar(251) DEFAULT NULL,
  `Mode` varchar(251) DEFAULT NULL,
  `lastTotal` decimal(10,2) DEFAULT NULL,
  `operator` varchar(30) DEFAULT NULL,
  PRIMARY KEY (`RecordID`),
  KEY `fk_operator` (`operator`),
  KEY `idx_topup_studio` (`studio`),
  KEY `idx_topup_studio_username` (`studio`,`UserName`),
  KEY `idx_topup_record_date` (`RecordDate`),
  CONSTRAINT `fk_studio` FOREIGN KEY (`studio`) REFERENCES `masterstudio` (`Studio`) ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=31000 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
